local PlantSupportMaker = {}
local PRODUCTS = {
    iron_plantsupport = { name = "Železni opora za rastline", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni opora za rastline za vrtove." },
    bronze_plantsupport = { name = "Bronast opora za rastline", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast opora za rastline za vrtove." },
    silver_plantsupport = { name = "Srebrn opora za rastline", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn opora za rastline za vrtove." },
    gilded_plantsupport = { name = "Pozlačen opora za rastline", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen opora za rastline za vrtove." },
    jewel_set_plantsupport = { name = "Draguljast opora za rastline", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast opora za rastline za vrtove." },
    royal_sovereign_plantsupport = { name = "Kraljevski suveren opora za rastline", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren opora za rastline z biseri za krono." },
}
local BUILDINGS = {
    plantsupport_workshop = { name = "Plantsupport delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    plantsupport_house = { name = "Plantsupport hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_plantsupport_atelier = { name = "Mojstrski plantsupport atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_plantsupport_palace = { name = "Suverena plantsupport palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PlantSupportMaker.ironStock = 14; PlantSupportMaker.bronzeStock = 12; PlantSupportMaker.woodStock = 16; PlantSupportMaker.leatherStock = 8; PlantSupportMaker.silverStock = 8; PlantSupportMaker.goldStock = 6; PlantSupportMaker.jewelStock = 4; PlantSupportMaker.pearlStock = 4
PlantSupportMaker.productStock = {}; PlantSupportMaker.buildings = {}; PlantSupportMaker.maker = nil; PlantSupportMaker.activeMaking = {}; PlantSupportMaker.totalProducts = 0; PlantSupportMaker.dayTimer = 0
function PlantSupportMaker.init() PlantSupportMaker.ironStock=14; PlantSupportMaker.bronzeStock=12; PlantSupportMaker.woodStock=16; PlantSupportMaker.leatherStock=8; PlantSupportMaker.silverStock=8; PlantSupportMaker.goldStock=6; PlantSupportMaker.jewelStock=4; PlantSupportMaker.pearlStock=4; PlantSupportMaker.productStock={}; PlantSupportMaker.buildings={}; PlantSupportMaker.maker=nil; PlantSupportMaker.activeMaking={}; PlantSupportMaker.totalProducts=0; PlantSupportMaker.dayTimer=0; print("[PlantSupportMaker] Royal Plant Support Maker System initialized (6 products, 4 buildings)") end
function PlantSupportMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlantSupportMaker.maker={name=n or ("Opornik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opornik najet: %s (spretnost: %d)",PlantSupportMaker.maker.name,s),"success") end; return true end
function PlantSupportMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlantSupportMaker.build(id) local ok,e=PlantSupportMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlantSupportMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlantSupportMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlantSupportMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlantSupportMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlantSupportMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlantSupportMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlantSupportMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlantSupportMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlantSupportMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlantSupportMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlantSupportMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlantSupportMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlantSupportMaker.buildings==0 then return false,"Potrebna oporna delavnica" end; if not PlantSupportMaker.maker then return false,"Potreben opornik" end; return true end
function PlantSupportMaker.make(pt,qty) qty=qty or 1; local ok,e=PlantSupportMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlantSupportMaker.ironStock=PlantSupportMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlantSupportMaker.bronzeStock=PlantSupportMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlantSupportMaker.woodStock=PlantSupportMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlantSupportMaker.leatherStock=PlantSupportMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlantSupportMaker.silverStock=PlantSupportMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlantSupportMaker.goldStock=PlantSupportMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlantSupportMaker.jewelStock=PlantSupportMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlantSupportMaker.pearlStock=PlantSupportMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlantSupportMaker.maker then t=math.max(1,t-math.floor(PlantSupportMaker.maker.skill/13)) end; table.insert(PlantSupportMaker.activeMaking,{id="plantsupport_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlantSupportMaker.completeMaking(m) local q=1.0+(PlantSupportMaker.getQualityBonus()/100); if PlantSupportMaker.maker then q=q+(PlantSupportMaker.maker.skill/140) end; q=math.min(2.5,q); PlantSupportMaker.productStock[m.productType]=(PlantSupportMaker.productStock[m.productType] or 0)+m.quantity; PlantSupportMaker.totalProducts=PlantSupportMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlantSupportMaker.maker then PlantSupportMaker.maker.itemsMade=PlantSupportMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlantSupportMaker.maker.skill=math.min(100,PlantSupportMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opora izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plantsupport.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlantSupportMaker.update(dt) if not _G.state then return end; PlantSupportMaker.dayTimer=PlantSupportMaker.dayTimer+dt; if PlantSupportMaker.dayTimer>=30 then PlantSupportMaker.dayTimer=0; for i=#PlantSupportMaker.activeMaking,1,-1 do local m=PlantSupportMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlantSupportMaker.completeMaking(m); table.remove(PlantSupportMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlantSupportMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlantSupportMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlantSupportMaker.getStats() return {ironStock=PlantSupportMaker.ironStock,bronzeStock=PlantSupportMaker.bronzeStock,woodStock=PlantSupportMaker.woodStock,leatherStock=PlantSupportMaker.leatherStock,silverStock=PlantSupportMaker.silverStock,goldStock=PlantSupportMaker.goldStock,jewelStock=PlantSupportMaker.jewelStock,pearlStock=PlantSupportMaker.pearlStock,productStock=PlantSupportMaker.productStock,numBuildings=#PlantSupportMaker.buildings,hasMaker=PlantSupportMaker.maker~=nil,makerName=PlantSupportMaker.maker and PlantSupportMaker.maker.name or "—",makerSkill=PlantSupportMaker.maker and PlantSupportMaker.maker.skill or 0,activeMaking=#PlantSupportMaker.activeMaking,totalProducts=PlantSupportMaker.totalProducts} end
return PlantSupportMaker
